Extract one hook beside Slider, at client/src/components/ui/Slider/useSliderDraft.ts:
```ts
export function useSliderDraft(committed: number, onCommit: (next: number) => void) {
  const [draft, setDraft] = useState<number | null>(null);
  return {
    value: draft ?? committed,
    onChange: setDraft,
    onCommit: (next: number) => { setDraft(null); onCommit(next); },
  };
}
```
